import { useState } from "react";
import { BoardState } from "../types";

const initialData: BoardState = {
  cards: {
    "1": { id: "1", title: "Task 1" },
    "2": { id: "2", title: "Task 2" },
    "3": { id: "3", title: "Task 3" },
  },
  columns: {
    todo: {
      id: "todo",
      title: "Todo",
      cardIds: ["1", "2"],
    },
    doing: {
      id: "doing",
      title: "Doing",
      cardIds: ["3"],
    },
    done: {
      id: "done",
      title: "Done",
      cardIds: [],
    },
  },
  columnOrder: ["todo", "doing", "done"],
};

export function useBoard() {
  const [board, setBoard] = useState(initialData);

  return {
    board,
    setBoard,
  };
}
